// ---------------------------------------------------------------------------
// Full UNSTUCK program data - every session, both phases.
// Source: UNSTUCK Daily Quick Cards + Main Program.
//
// Structure: two PHASES (Foundation = Weeks 1-2, Progression = Weeks 3-4).
// Each phase has 5 days; each day has its exercises with per-tier instructions.
// The Program screen lets you pick a week (1-4) -> which maps to a phase -> day.
// ---------------------------------------------------------------------------

import type { Tier } from "./dummyContent";

export interface Exercise {
  name: string;
  setsReps: string;
  how: string;
  keyFocus: string;
  why: string;
  tier: Record<Tier, string>;
  notes: string;
  contraindications?: string;
  image?: string;
}

export interface ProgramDay {
  day: number;          // 1..5
  focus: string;        // e.g. "Hips & Hamstrings"
  exercises: Exercise[];
}

export interface Phase {
  id: "foundation" | "progression";
  label: string;        // "Foundation (Weeks 1-2)"
  weeks: number[];      // [1,2] or [3,4]
  duration: string;
  effort: string;
  warmup: string;
  days: ProgramDay[];
}

// Helper: when all tiers share the same instruction.
const all = (s: string): Record<Tier, string> => ({ green: s, amber: s, red: s });

