// Map a week number (1-4) to its phase.
export function phaseForWeek(week: number): Phase {
  return week <= 2 ? phases[0] : phases[1];
}

// Flat list of weekly sessions for the worksheet check-off log (Cards tab).
export const weekSessions = phases.flatMap((p) =>
  p.weeks.map((week) => ({ week, phase: p, days: p.days }))
);
